Return JSON:
{"interview_summary":"3-4 sentences: who this person is, what they're trying to accomplish, and the most important thing this interview revealed","top_job_to_be_done":"the primary outcome this customer is trying to achieve — in their language","current_workflow":"how they currently accomplish this — tools, steps, workarounds","pain_points":[{"pain":"specific pain described","severity":"critical|significant|minor","quote":"verbatim quote or close paraphrase that captures this pain","workaround":"what they do instead"}],"desired_outcomes":["what they want to be true — not features, but outcomes in their language"],"surprising_findings":["things that contradicted assumptions or were unexpected"],"hypothesis_assessment":[{"hypothesis":"","verdict":"confirmed|contradicted|partially_confirmed|not_addressed","evidence":"what in the transcript supports this verdict"}],"pull_quotes":[{"quote":"","context":"why this quote matters","usable_for":"what this quote could be used for — persona, sales deck, design review, etc."}],"follow_up_questions":["questions this interview raised that should be asked in future interviews"],"product_implications":["specific things the product team should consider based on this interview"]}
